NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'Hosea'

CHAPTERS = {
    1: {
        1: 'Herrens ord som kom til Hosea, son åt Be’eri, i dei dagarne då Uzzia, Jotam, Ahaz og Hizkia var kongar i Juda, og då Jeroboam, son åt Joas, var konge i Israel.',
        2: 'Herrens fyrste ord til Hosea var at han sagde til honom: «Gakk stad og få deg ei horkona og horeborn! For landet driv på med hor og fer soleis burt ifrå Herren.»',
        3: 'Då gjekk han stad og gifte seg med Gomer dotter, hans Diblajim. Og ho vart med barn og fødde honom ein son.',
        4: 'Og Herren sagde til honom: «Lat honom heita Jizre’el! For um ein stakkut stund vil eg lata huset hans Jehu lida for Jizre’els blodskuld og gjera ende på kongedømet i Israels hus.',
        5: 'Den dagen skal det bera so til at eg bryt sund Israels boge i Jizre’els dal.»',
        6: 'Og ho vart med barn att og fekk ei dotter. Då sagde han til honom: «Lat henne heita Lo-Ruhama! For eg kjem ikkje lenger til å miskunna Israels hus, so eg tilgjev deim.',
        7: 'Men Judas hus miskunnar eg og let deim verta frelste av Herren, deira Gud. Men med boge og sverd og krig, med hestar og ridarar frelser eg deim ikkje.»',
        8: 'Då ho hadde vant av Lo-Ruhama, vart ho med barn att og fekk ein son.',
        9: 'Då sagde han: «Lat honom heita Lo-Ammi! For de er ikkje mitt folk, ikkje heller skal eg høyra dykk til.»',
        10: 'Men talet på Israels born skal vera som sanden på havsens strand, den som ikkje kann mælast eller teljast. Og det skal verta so, at der ein fyrr sagde til deim: «De er ikkje mitt folk,» der skal ein segja til deim: «Borni åt den livande Gud.»',
        11: 'Og Juda-borni og Israels-borni skal fylkja seg saman og velja seg ein konge og fara upp or landet. For stor er Jizre’els dag.',
    },
    2: {
        1: 'Seg då til brørne dykkar: «Ammi»! og til systerne dykkar: «Ru-hama»!',
        2: 'Skjem på mor dykkar, skjem! For ho er ikkje kona mi, og eg er ikkje mannen hennar. Lat henne få burt horebragderne or andlitet sitt og lauslynde-merket frå barmen sin!',
        3: 'Elles skal eg klæda av henne, so ho ligg naki: Eg skal te henne fram som den dagen ho vart fødd. Eg skal gjera henne lik ei øydemark og ei turr-audn, og lata henne døy av torste.',
        4: 'Og borni hennar, ikkje vil eg miskunna deim; for horeborn er dei.',
        5: 'For mor deira var ei horkvinna, ho som fekk deim, for skamleg åt, med di ho sagde: «Eg vil fara etter elskarane mine. For dei gjev meg maten min og drykken min, ulli mi og linet mitt, oljen min og vinen min.»',
        6: 'Sjå, difor stengjer vil eg stengja vegen din med tornar. Ja, ein mur skal eg setja upp framfyre henne, so ho ikkje skal finna stigarne sine.',
        7: 'Når ho då renner etter elskarane sine, skal ho ikkje nå i deim, når ho leitar etter deim, skal ho ikkje finna deim. Då skal ho segja: «Eg vil attende til den fyrste mannen min. For betre hadde eg det då enn no.»',
        8: 'Og ho, ikkje skyna ho at det var eg som gav henne kornet og druvesafti og oljen, og som var storgjæv imot henne med sylv og med gull, som dei nytta ut for Ba’al.',
        9: 'Difor skal eg taka att kornet mitt når korntidi kjem, og druvesafti mi i rette stundi, og taka burt ulli mi og linet mitt, det som ho skulde løyna blygsli si med.',
        10: 'Ja, no skal eg nækja blygsli hennar beint for augo på elskarane hennar, og ingen skal berga henne or mi hand.',
        11: 'Og eg skal gjera ende på all kjæta hennar, på gildi hennar, nymånarne og kviledagarne og alle høgtiderne hennar.',
        12: 'Eg skal øyda vintrei og fiketrei hennar, som ho sagde um: «Dei er meg ei løn som elskarane mine gav meg.» Og eg skal gjera deim til villkjør som villdyri skal eta av.',
        13: 'Soleis skal eg refsa henne for Ba’als-dagarne hennar, då ho brende røykjelse for deim og prydde seg med nasering og bringespenne og for etter elskarane sine, men gløymde meg, segjer Herren.',
        14: 'Difor skal de vita at eg vil lokka henne burt og leida henne ut i villmarki, so eg kan få tala hjarteord med henne.',
        15: 'So vil eg derifrå gjeva henne att vinhagarne hennar, og gjera Akordalen til eit vonarled. Der skal ho syngja som i ungdomsdagarne sine, og som då ho for upp frå Egyptarlandet.',
        16: 'Og den dagen, segjer Herren, kjem det til å verta so at du ropar til meg: «Mannen min!» Og du skal ikkje meir ropa til meg: «Ba’al min!»',
        17: 'Ja, Ba’als-namni vil eg taka reint ut or munnen hennar, so dei aldri skal nemnast meir.',
        18: 'Den dagen gjer eg for deim ei pakt med dyri på marki, med fuglarne under himmelen og med kreket på jordi. Og boge og sverd og krig bryt eg sund. Eg skal få det reint ut or landet, og lata deim bu trygt.',
        19: 'Og eg vil trulova meg med deg til æveleg tid. Eg vil trulova meg med deg i rettferd og rett, i nåde og miskunn.',
        20: 'Ja, i truskap vil eg trulova meg med deg, og du skal kjenna Herren.',
        21: 'Og den dagen kjem det til å verta so at eg bønhøyrer, segjer Herren, eg bønhøyrer himmelen, og han bønhøyrer jordi.',
        22: 'Og jordi skal bønhøyra kornet og druvesafti og oljen, og dei skal bønhøyra Jizre’el.',
        23: 'Og plantar meg henne i landet og miskunnar Lo-Ruhama, og eg segjer til Lo-Ammi: «Folket mitt er du!» og ho, ho skal segja: «Min Gud!»',
    },
    3: {
        1: 'Og Herren sagde til meg: «Gakk ein gong til stad og elska ei kvinna som hev ein elskar og er ei lauslyndt kvinna, liksom Herren elskar Israels-borni, endå dei vender seg til andre gudar og elskar druvekakor!»',
        2: 'Og eg kjøpte meg ei slik kvinna og gav for henne femtan sylvdalar og tri tunnor bygg og attpå halvonnor tunna bygg.',
        3: 'So sagde eg til henne: «I mange dagar vert du no sitjande for meg og fær ikkje gjera hor eller hava med nokon annan mann å gjera. So skal eg og taka det sameleis med deg.»',
        4: 'For i mange dagar skal Israels-borni sitja utan konge og hovding, utan ofring og bilætsulor, utan messehakel og husgudar.',
        5: 'So skal Israels-borni venda um og søkja Herren, sin Gud, og David, kongen sin. Og bivrande skal dei koma til Herren og til hans velsigning i dei seinste dagar.',
    },
    4: {
        1: 'Høyr Herrens ord, de Israels-born! For Herren hev sak med deim som bur i landet, av di det ingen truskap finst i landet, og ingen kjærleik og ingen kjennskap til Gud.',
        2: 'Dei sver og lyg, dei drep og stel og driv hor. Dei fer med vald, og blodverk fylgjer på blodverk.',
        3: 'Difor ligg landet i sorg, og alt som bur i det, sjuknar burt, både dyri på marki og fuglarne under himmelen. Jamvel fiskarne i havet set til.',
        4: 'Like vel skal ingen skjella og ingen refsa; for folket ditt er liksom dei som trettar med ein prest.',
        5: 'Ja, du skal falla um dagen, og profeten skal falla med deg um natti, og mor di tynar eg.',
        6: 'Det er ute med folket mitt, av di det vantar kunnskap. Etter di du hev vanda kunnskap, so skal eg og vanda deg, so du ikkje vert min prest. Og etter di hev gløymt lovi åt din Gud, so skal eg og gløyma borni dine.',
        7: 'Di fleire dei vart, di meir synda dei mot meg. Men deira heider skal eg snu um til vanheider.',
        8: 'Av mitt folks synd nærer dei seg, og til misgjerningi deira stend deira hug.',
        9: 'Men no skal det ganga med presten som folket. Eg skal straffa deim for deira ferd, og gjeva deim att for deira gjerd.',
        10: 'Og eta skal dei og ikkje mettast, hora og ikkje meirast, av di dei hev slutta med å agta på Herren.',
        11: 'Horeliv og vin og mjød tek vitet burt.',
        12: 'Folket mitt spør stokken sin til råds, og hentar seg rettleiding av sin stav. For ei hordoms ånd hev villa deim, so dei med hor dreg seg burt ifrå sin Gud.',
        13: 'Øvst uppå åsarne ofrar dei, og på kollarne brenner dei røykjelse, under eik og poppel og terebinta, av di skuggen der er god. So vert døtterne dykkar skjøkjor og sonekonorne dykkar horkonor.',
        14: 'Likevel refsar eg ikkje døtterne dykkar for at dei er skjøkjor eller sonekonorne dykkar for at dei er horkonor. For mennerne sjølve løyner seg av med horkonor og ofrar med tempelskjøkjor. Soleis fer eit fåvitugt folk til sin undergang.',
        15: 'Um no du Israel vil halda på med ditt horeliv, so må då ikkje Juda skuldbinda seg soleis. Kom då ikkje til Gilgal, og far ikkje upp til Bet-Aven, og sver ikkje: «So sant som Herren liver.»',
        16: 'Um Israel stritar imot som ei balstyri ku, so skal Herren på hyrdingvis no føra deim som lamb på vidåtta.',
        17: 'Bunden til avgudsbilæte er Efraim. So fær han då fara!',
        18: 'Drikkinga deira er måtelaus. Hegdelaust driv dei sitt horeliv. Skjoldarne hennar elskar det som skamlegt er.',
        19: 'Med eit stormver skal gripa deim med vengjerne sine, og dei skal verta til skammar med ofringarne sine.',
    },
    5: {
        1: 'Høyr dette, de prestar, og gjev gaum, du Israels hus, og du kongehus, legg øyra til! For dykk gjeld domen. For det hev vore ei snara åt Mispa, og eit utspila net på Tabor.',
        2: 'Med ei offerslagting hev dei sokke berre djupare ned i villa. Men eg skal verta eit tukteris åt deim alle i hop.',
        3: 'Eg kjenner Efraim, og Israel er ikkje løynt burt ifrå meg. For du Efraim hev drive hor, og Israel hev sulka seg til.',
        4: 'Gjerningarne deira let deim ikkje få venda um til deira Gud, av di dei hev ei hordoms ånd i bringa si, og Herren, honom kjenner dei ikkje.',
        5: 'Men Israels storlæte vitnar imot honom, og Israel og Efraim skal stupa for si misgjerning. Juda skal og falla med deim.',
        6: 'Um dei fer av stad med sitt småfe og sitt storfe og skal søkja Herren, so finn dei honom ikkje. Han hev drege seg ifrå deim.',
        7: 'Mot Herren hev dei vore utrue. For dei hev født born som ikkje er hans. Difor skal no ein nymåne eta deim upp med alt det dei eig.',
        8: 'Blås i lur i Gibea, i trompet i Rama! Blås alarm i Bet-Aven! Etter deg, Benjamin!',
        9: 'Efraim skal øydast på refsingsdagen. Mot Israelsfylki varslar eg det visse.',
        10: 'Juda hovdingar hev vorte liksom dei som flyt deilder. Yver deim skal eg ausa ut vreiden min som vatn.',
        11: 'Efraim vert nedkua, retten hans rana. For han hev teke på med å fara etter menneskjebod.',
        12: 'Og eg - som mol er eg no for Efraim og som beinåt for Judas hus.',
        13: 'Og Efraim hev gått sjukdomen sin og Juda såret sitt. Difor hev Efraim fare til Assur og sendt bod til kong Jareb. Men han kann ikkje gjera dykk gode att, og såret dykkar vert ikkje lækt.',
        14: 'For eg, som ei løva er eg mot Efraim og som ei ungløva mot Juda hus. Og eg, ja eg riv sund og fer min veg med det, og ikkje finst den som kann berga.',
        15: 'Eg gjeng min veg attende til min stad, til dess dei hev lide det dei hev fortent, og so fer til å søkja mi åsyn. I si naud skal dei leita etter meg.',
    },
    6: {
        1: '«Kom, lat oss venda um til Herren! For det er han som hev såra, og han vil lækja oss. Han slo, men vil og fetla oss.',
        2: 'Han skal gjera oss livande um tvo dagar, den tridje dagen skal han reisa oss upp att, og me skal liva framfor hans åsyn.',
        3: 'So lat oss læra å kjenna, ja, lat oss strida for å læra kjenna Herren! Han renn upp so visst som morgonroden. Og han kjem nedyver oss som regnet, som eit vårregn som væter jordi.»',
        4: 'Kva skal eg gjera med deg, Efraim? Kva skal eg gjera med deg, Juda? For kjærleiken dykkar er som ei morgonsky, liksom doggi som tidleg kverv.',
        5: 'Difor hev eg gjeve hogg ved profetarne. Eg hev drepe deim med min munns ord, og domarane dine for ut som ljoset.',
        6: 'For eg hev hug til kjærleik og ikkje til slagtoffer, og til Guds-kunnskap meir enn til brennoffer.',
        7: 'Men dei hev brote pakti som Adam. Der hev dei vore utrue mot meg.',
        8: 'Gilead er ein by for illgjerningsmenner, full av blodfar.',
        9: 'Og som ein røvarflokk som ligg på lur etter folk, er heile prestehopen; dei drep på vegen til Sikem. Ja, skamlaust fer dei åt.',
        10: 'I Israels hus hev eg set gruvelege ting. Der driv Efraim på med hor, sulkar Israel seg til.',
        11: 'Ogso for deg, Juda, er tiletla ei skurdonn, når eg vender mitt folks lagnad.',
    },
    7: {
        1: 'Når eg vil lækja Israel, då kjem misgjerningi åt Efraim og vondskapen åt Samaria til synes. For dei driv med fals, og tjuv bryt seg inn, og rekarfant plundrar på vegarne.',
        2: 'Og dei segjer ikkje med seg sjølve seg at eg minnast all deira vondskap. No er dei ringa inne av sine eigne gjerningar, dei er komne framfyre mi åsyn.',
        3: 'Med vondskapen sin fegnar dei kongen, og hovdingarne med lygnerne sine.',
        4: 'Alle i hop er dei horkarar. Dei likjest ein omn som bakaren hitar upp. Han held upp med eldingi frå di han knodar deigen til dess ho er syrt.',
        5: 'På dagen åt kongen vår drikk hovdingarne seg sjuke på heit vin. Sjølv tek han spottarar i handi.',
        6: 'Når dei med meinråderne sine hev elda hugen sin som ein omn, søv bakaren deira heile natti. Um morgonen brenn han som logande eld.',
        7: 'Alle i hop er dei heite som ein omn og brenner upp domarane sine. Alle kongarne deira fell, og det er ingen av deim som kallar på meg.',
        8: 'Efraim, med folki mengjer han seg. Efraim hev vorte som ei kaka som ikkje er vend.',
        9: 'Framande hev tært upp krafti hans, og han skyner inkje. Um håret hans hev vorte gråsprengt, so skynar han inkje.',
        10: 'Men Israels ovmod vitnar imot honom midt uppi syni. Dei vender ikkje um til Herren, sin Gud, og ikkje søkjer dei honom, tråss i alt dette.',
        11: 'Efraim hev vorte som ei fåvis duva som inkje veit. Egyptarland ropar dei på, til Assur fer dei.',
        12: 'Men best som dei fer av stad, breider eg netet mitt utyver deim og dreg deim ned, liksom ein gjer med fuglarne i lufti. Eg skal tukta deim, som lyden deira alt hev høyrt.',
        13: 'Usæle dei, at dei flaug ifrå meg! Øyding yver deim, av di dei hev svike meg! Og eg, utløysa deim vilde eg. Men dei, ljugartale hev dei fare med imot meg.',
        14: 'Og ikkje ropar dei til meg av hjarta; dei berre jamrar seg på sengjerne sine. For korn og druvesaft samlar dei seg, medan dei vender seg frå meg.',
        15: 'Det var eg som lærde deim upp, og som styrkte armarne deira. Men imot meg hev dei ilt i hugen.',
        16: 'Dei vender um, men ikkje uppetter. Dei er liksom ein sviksam boge. Falla for sverd skal hovdingarne deira for si hatige tunga skuld. For det vert dei hædde i Egyptarlandet.',
    },
    8: {
        1: 'Til munnen din med luren! Som ein ørn yver Herrens hus! av di dei hev brote mi pakt og falle frå mi lov.',
        2: 'Dei ropar til meg: «Min Gud! Me, Israel, kjenner deg!»',
        3: 'Men av di Israel hev støytt frå seg det som godt er, skal fienden elta honom.',
        4: 'Dei, kongar valde seg som ikkje var ifrå meg. Hovdingar tok dei seg, og eg fekk ikkje vita um det. Av sylvet sitt og gullet sitt gjorde dei seg gudebilæte, so dei skulde verta utrudde.',
        5: 'Ufyseleg er kalven din, Samaria! Harmen min logar imot deim. Kor lenge skal det vara at dei ikkje kann tola reinleik?',
        6: 'For frå Israel er kalven komen. Ein meister hev laga honom, og nokon gud er han ikkje. Difor skal Samariakalven smuldrast i smått.',
        7: 'For vind sår dei, og storm skal dei hausta. Avling skal dei ikkje få, grøda skal ikkje gjeva føda, og um ho det gjer, skal framande eta det upp.',
        8: 'Gløypt vert Israel. Millom folki er dei alt som ein verdlaus ting.',
        9: 'For dei hev fare upp til Assur liksom eit villasen som gjeng sin eigen veg. Efraim tingar um elsk.',
        10: 'Men kor so dei tingar millom folki, so skal no eg like vel klemba deim i hop og lata deim få ei låk tid under storkongens trælking.',
        11: 'Av di Efraim hev gjort seg so mange altar til synd, so skal og altari hans verta honom til synd.',
        12: 'Um eg skriv lover åt han i titusundtal, so reknar han deim berre som framande lover.',
        13: 'Til slagtoffergåvor åt meg ofrar dei kjøt som dei et - Herren hev ikkje hugnad i deim. No kjem han i hug misgjerningarne deira og heimsøkjer deira synder. Dei skal fara attende til Egyptarland.',
        14: 'Og etter di Israel hev gløymt skaparen sin og bygt seg borgar, og Juda hev sett seg upp mange borgfaste byar, so skal eg senda eld mot byarne hans, og han skal øyda borgerne hans.',
    },
    9: {
        1: 'Gled deg ikkje, Israel, med fagnad liksom folki, av di du hev drive på med hor og dermed kome burt ifrå din Gud, du som hev havt din hugnad i skjøkjeløn på alle korn-treskjarstader.',
        2: 'Treskjestaden og vinpersa skal ikkje kunna næra deim, og druvesafti skal mislukkast for deim.',
        3: 'Ikkje skal dei få bu i Herrens land. Men Efraim skal attende til Egyptarland, og i Assur skal dei eta det som ureint er.',
        4: 'Dei skal ikkje renna ut vin til drykkoffer for Herren, og ikkje skal slagtofferi deira vera hugsame for honom; som syrgjebrød for deim. Alle som et av det, skal verta ureine. For brødet sitt hev dei berre for seg sjølve, det kjem ikkje i Herrens hus.',
        5: 'Kva skal de so gjera på helgedagen, på Herrens høgtidsdag?',
        6: 'For de skal vita at um dei slepp undan avøydingi, so vert det Egyptarlandet som samlar deim, Mof som fær å jorda deim. Sylvet deira, det dyre, skal netlor eiga, tistel veksa i tjeldbuderne deira.',
        7: 'Dei kjem, heimsøkjingsdagarne, dei kjem, attergjeldsdagarne. Det fær nok Israel vita. Ein dåre er profeten, vitlaus er åndsmannen, for di store misgjerning skuld, og for din sterke fiendskap.',
        8: 'Ein lurar er Efraim imot min Gud. Profeten - fuglefangarsnara på alle hans vegar, fiendskap i gudshuset hans!',
        9: 'Djupt i used hev dei sokke som i Gibea-dagarne. Men han hugsar misgjerningi deira, han heimsøkjer deira synder.',
        10: 'Liksom druvor i villmarki fann eg Israel. Som frumsefrukt på fiketre i den fyrste bering såg eg federne dykkar. Men dei kom til Ba’al-Peor, og vigde seg til skjemdarguden, og dei vart til styggedom liksom han som dei elska.',
        11: 'Efraim - som ein fugl skal herlegdomen hans fljuga burt. Ingen skal få born meir, ingen vera med barn, og ingen verta umhender.',
        12: 'For um dei el upp borni sine, so gjer eg deim barnlause, so det ikkje finst menneskje att. Ja, usæle er og dei sjølve når eg gjeng ifrå deim!',
        13: 'Efraim, som eg ser honom alt burt til Tyrus, er planta på ein eng. Men Efraim skal verta nøydd til å føra borni sine ut til rettarmannen.',
        14: 'Gjev deim, Herre! Kva skal du gjeva deim? Gjev deim moderfang som føder i utid, og brjost som turkast upp.',
        15: 'All deira vondskap er samla i Gilgal. Ja, der fekk eg hat til deim. For deira vonde åtferd skuld vil eg driva deim ut or mitt hus. Ikkje skal eg elska deim lenger. Alle deira førarar er upprørarar.',
        16: 'Stungen er Efraim, roti deira turka, frukt skal dei ikkje bera. Og um dei fær born, drep eg den dyre livsfrukti deira.',
        17: 'Min Gud skal støyta deim burt; for ikkje lydde deim på honom, og dei skal flakka heimlause ikring millom folki.',
    },
    10: {
        1: 'Eit rikt vintre er Israel og ber frukt. Men di meir frukt han fekk, di meir auka han talet altari sine. Di betre det gjekk for landet hans, di betre gjorde han minnesteinarne.',
        2: 'Hjarto deira var falske, no skal dei få bøta. Han skal brjota ned altari deira og slå sund deira minnesteinar.',
        3: 'Ja, no skal dei segja: «Ingen konge hev me, for me hev ikkje ottast Herren. Og kongen, kva kann vel han gjera for oss?»',
        4: 'Tala tome ord, sverja falskt, gjera semja! Og domen renn upp som beiskt ugras på åkerforerne.',
        5: 'For kalven i Bet-Aven er Samaria-buarne ottefulle. Ja, folket hans syrgjer yver honom, og prestarne hans skjelv for honom, for herlegdomen hans, av di han er førd burt ifrå honom.',
        6: 'Han sjølv skal førast til Assur, ei gåva til kong Jareb. Skam skal Efraim henta seg, skjemmast skal Israel for rådgjerdi si.',
        7: 'Ute er det med Samaria-kongen, som ei treflis på vatnet rek han av.',
        8: 'Øydast skal Avens offerhaugar, Israels synd. Torn og tistel skal renna upp på altari deira. Og dei skal segja til fjelli: «Gøym oss!» og til haugarne: «Velt dykk yver oss!»',
        9: 'Radt ifrå Gibea-dagarne hev du synda, Israel! Der hev du stade. Skulde han ikkje nå deim i Gibea, krigen mot nidingarne?',
        10: 'Når eg hev hug til det, tuktar eg deim. Og folki samlar seg imot deim og bind deim fast til tvifalds-syndi deira.',
        11: 'Og Efraim er ei tamd kviga som likar å treskja. Og eg hev spart den fagre halsen hennar. No vil eg leggja oket på Efraim. Juda skal pløgja, Jakob skal horva.',
        12: 'Så åt dykk som rettferd krev, hausta etter kjærleiks lov! Brjot dykk nybrot! For det er tid til å søkja Herren, so han kann koma og lata rettferd regna yver dykk.',
        13: 'De hev pløgt gudløysa, rettløysa hev de hausta. De hev ete lygjefrukt, med di du hev sett lit til vegen din, til mengdi av kjemporne dine.',
        14: 'Med det reiser seg ein stridsdun millom fylki dine, og alle borgfesti dine skal falla, liksom Bet-Arbel vart lagt i øyde av Salman den stridsdagen då dei krasa både mor og barn.',
        15: 'Slikt skal Betel føra yver dykk for dykkar store vondskap. Når morgonen rodar, er det ute, ute med Israels-kongen.',
    },
    11: {
        1: 'Då Israel var ung, hadde eg honom kjær, og ut or Egyptarland kalla eg son min.',
        2: 'Di meir dei kalla på deim, di meir gjekk dei burt ifrå deim. Åt Ba’alarne ofrer dei, åt bilæti brenner dei røykjelse.',
        3: 'Og det var då eg som lærde Efraim å ganga, tok deim på armarne mine. Og ikkje skyna dei at eg lækte deim.',
        4: 'Med menneskjesnorer drog eg deim, med kjærleiksband. Og eg var deim som dei som lettar oket yver kjakarne deira, og eg bøygde meg ned til honom og let honom få mat.',
        5: 'Han skal ikkje fara attende til Egyptarland; men Assur, han skal vera kongen hans, for dei vilde ikkje venda um.',
        6: 'Og sverd skal rasa i byarne hans og brjota bommarne hans og eta ikring seg - for deira uråder skuld.',
        7: 'Og folket mitt er huga på fråfall frå meg. Og um ein kallar deim til det høge, so er det ingen som lettar på seg.',
        8: 'Korleis skal eg nenna gjeva deg upp, Efraim? Korleis skal eg lata deg fara, Israel? Kann eg nenna gjeva deg upp som Adma, gjera med deg som med Sebojim? Hjarta mitt vrid seg i meg, all mi vårkunn vaknar.',
        9: 'Eg vil ikkje lata deg kjenna min brennande harm. Ikkje vil eg atter tyna Efraim. For Gud er eg og ikkje eit menneskje. Heilag er eg midt i deg, og med vreide vil eg ikkje koma.',
        10: 'Etter Herren skal dei då fylgja, som ei løva skal han bura. Ja, han skal bura, og bivrande skal born koma frå havet.',
        11: 'Bivrande skal dei koma som fuglar frå Egyptarland og som duvor frå Assurs land. Og eg vil lata deim bu i husi sine, segjer Herren.',
    },
    12: {
        1: 'Efraim hev ringa meg inn med lygn, og Israels hus med svik. Og Juda er alljamt agelaus imot Gud, mot den Heilage, den Trufaste.',
        2: 'Efraim stundar etter vind, og jagtar etter austanver. All dagen aukar det på med lygn og vald. Samband med Assur gjer dei, og olje fører dei til Egyptarland.',
        3: 'Men Herren fører sak med Juda, og vil heimsøkja Jakob for åtferdi hans, betala honom etter gjerningarne hans.',
        4: 'I morslivet heldt han bror sin i hælen, og i si manndomskraft drogst han med Gud.',
        5: 'Ja, han drogst med engelen og vann, han gret og bad honom um nåde. I Betel fann han honom, og der tala han med oss.',
        6: 'Og Herren, allhers Gud - «Herren» er hans ærenamn.',
        7: 'Og du, til din Gud skal du venda um. Hald fast på kjærleik og rett! Og bia stødt på din Gud!',
        8: 'Kana’an, i handi hans er falsk vegt. Å gjera urett likar han.',
        9: 'So segjer og Efraim: «Eg hev då vorte rik, eg hev vunne meg midel. Kva eg so strævar med, so skal dei då ikkje finna hjå meg nokon urett som er synd.»',
        10: 'Men eg er Herren din Gud, alt ifrå Egyptarland, eg vil endå lata deg bu i tjeldbuder liksom i høgtidsdagarne.',
        11: 'Og eg hev tala til profetarne, og eg, syner i mengd hev late deim sjå, og gjenom profetarne hev eg tala i liknader.',
        12: 'Er no Gilead eit illgjerdsreir, so skal dei verta berre fåfengd. Ofrar dei uksar i Gilgal, so skal og altari deira verta som steinrøysar innmed forerne på marki.',
        13: 'Og Jakob rømde til Aramsletta, og Israel træla for ei kona - og for ei kona gjætte han.',
        14: 'Men ved ein profet førde Herren Israel frå Egyptarland, og ved ein profet gjætte han honom. Sår harm hev Efraim valde. Difor skal Herren hans lata blodskuldi hans koma yver honom, og han skal venda hans skjemdarferd mot honom sjølv.',
    },
    13: {
        1: 'Når Efraim tala, vart dei fælne. Høg var han i Israel. Men han vart saka med Ba’al og døydde.',
        2: 'Og no held dei på med si synd. Og dei gjer seg støypte bilæte av sylvet sitt, avgudar etter sitt eige vit, handverksarbeid alt saman. Til slike talar dei. Menneskjeslagtarar kysser kalvar.',
        3: 'Difor skal dei verta som morgonskyi, som doggi som tidleg kverv, liksom agner som vinden fyk burt ifrå treskjarstaden, og liksom røyk or ein ljore.',
        4: 'Men eg er Herren, din Gud, alt frå Egyptarland. Nokon annan Gud enn meg veit du ikkje av. Og nokon annan frelsar enn eg finst ikkje.',
        5: 'Det var eg som kjendest ved deg i øydemarki, i det turre landet.',
        6: 'Etter som beitet deira var, vart dei mette. Då dei var mette, vart dei høge i sin hug. Difor gløymde dei meg.',
        7: 'Då vart eg deim liksom ei løva. Som ein pantar lurer eg innmed vegen.',
        8: 'Eg kjem yver deim som ei binna som dei hev teke ungarne ifrå, og riv sund bringa deira. Eg gløypar deim som ei løvemor. Villdyr skal slita deim sund.',
        9: 'Du hev tynt deg, Israel, med di du er imot meg, di hjelp.',
        10: 'Kvar er no kongen din, at han kann syta for frelsing åt deg i alle byarne dine? Og kvar hev du domarane dine, som du sagde um: «Lat meg få konge og hovdingar?»',
        11: 'Ja, ein konge skal eg gjeva deg i min vreide, og so tek eg honom burt i min harm.',
        12: 'Samanbundi er misgjerningi hans Efraim, og syndi hans gøymd.',
        13: 'Rider som hjå ei fødande kvinna skal koma yver honom. Han er ein son som ikkje er vis. For når stundi er der, kjem han ikkje fram i fødsli.',
        14: 'Or helheims vald vil eg fria deim, frå dauden vil eg løysa deim ut. Kvar er di sott, du daude? Kvar er di tyning, du helheim? Anger er løynd for augo mine.',
        15: 'For han, millom brørne sine stend han lavande av frukt; det kjem ein austanvind, eit Herrens ver, farande upp ifrå øydemarki. Då turkar brunnen hans upp, og kjelda hans tryt. Han ranar skatten, alle slag kostnadting.',
    },
    14: {
        1: 'Bøta skal Samaria, av di det hev vore tråssugt imot sin Gud. For sverd skal dei falla, småborni deira skal verta krasa, og dei kvinnor som er med barn, skal ristast upp.',
        2: 'Vend um, du Israel, til Herren, din Gud! For med di misgjerning hev du ført deg i fall.',
        3: 'Tak med dykk ord, og vend um til Herren! Seg til honom: «Forlat all misgjerning og tak imot det som godt er, lat oss betala med uksar - med våre lippor!',
        4: 'Assur skal ikkje frelsa oss. På hestar skal me ikkje rida. Og ikkje meir skal me segja: «Vår Gud!» til det som henderne våre hev gjort. For hjå deg er det at den faderlause fær miskunn.»',
        5: 'Ja, deira fråfall vil eg lækja. Eg vil elska deim av fri hug, av di vreiden min hev vendt seg ifrå deim.',
        6: 'Eg skal vera som dogg for Israel. Bløma skal han som ei lilja, og røtast skal han som Libanon.',
        7: 'Renningarne hans skal spreida seg, og skal vera som eit oljetre i fagerleik, og anga som Libanon.',
        8: 'Dei som bur i skuggen hans, skal atter avla korn og bløma som vintreet. Minnet um honom skal vera som vin ifrå Libanon.',
        9: 'Men du, Efraim! Kva skal eg med avgudarne meir? Eg bønhøyrer og ser til honom. Eg er som eit grønt cypresstre. Frå meg skal di frukt vera å finna. Den som er vis, han agte på dette, den som er vitug, merke seg det! For Herrens vegar er rette, og rettvise ferdast på deim, men illgjerdsmenner stuper på deim.',
    },
}
